package com.dunerealms.clans;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import java.sql.*;import java.math.*;import java.util.*;
class KitFeeStoreTest{
 String url;ClanStore s;ClanMoneyStore bank;ClanStore.Context ctx;
 @BeforeEach void setup()throws Exception{url="jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";ctx=new ClanStore.Context("00000000-0000-0000-0009-000000000001","clan","member","Clan","CL",1,"design",1,"Kit","#123456","[]",100);s=new ClanStore((c,p)->ctx);bank=new ClanMoneyStore();try(Connection c=open()){ClanStore.initialize(c);ClanMoneyStore.initializeTreasury(c);ClanMoneyStore.initializeTreasury(c);try(Statement q=c.createStatement()){q.execute("CREATE TABLE dune_players(uuid VARCHAR(36) PRIMARY KEY,faction VARCHAR(64))");q.execute("CREATE TABLE dune_economy_balances(uuid VARCHAR(36) PRIMARY KEY,balance DECIMAL(20,2))");}try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_players VALUES(?,'Atreides')")){q.setString(1,ctx.uuid());q.executeUpdate();}try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_economy_balances VALUES(?,250)")){q.setString(1,ctx.uuid());q.executeUpdate();}}}
 Connection open()throws Exception{return DriverManager.getConnection(url);}BigDecimal scalar(Connection c,String sql)throws Exception{try(Statement q=c.createStatement();ResultSet r=q.executeQuery(sql)){r.next();return r.getBigDecimal(1);}}
 @Test void splitFloorsTaxesToCentsAndRecordsExactRemainder()throws Exception{for(String amount:List.of("0.01","1.01","99.99","100.00","1000000.00")){var split=KitFeeStore.split(new BigDecimal(amount));assertEquals(0,split.total().compareTo(split.faction().add(split.server()).add(split.sink())));assertEquals(new BigDecimal(amount).multiply(new BigDecimal("0.15")).setScale(2,RoundingMode.DOWN),split.faction());assertEquals(new BigDecimal(amount).multiply(new BigDecimal("0.05")).setScale(2,RoundingMode.DOWN),split.server());}var tiny=KitFeeStore.split(new BigDecimal("0.01"));assertEquals(new BigDecimal("0.01"),tiny.sink());}
 @Test void buyerActualFactionGets15Server5Sink80AndReplayCannotCreditTwice()throws Exception{UUID id=UUID.randomUUID();try(Connection c=open()){c.setAutoCommit(false);s.operation(c,id,ctx,"kit");s.payDunemarks(c,ctx);bank.treasuryFee(c,ctx,id);s.orderDunemarks(c,id,ctx);c.commit();assertEquals(new BigDecimal("150.00"),s.wallet(c,UUID.fromString(ctx.uuid())));assertEquals(new BigDecimal("15.00"),scalar(c,"SELECT balance FROM dune_faction_bank_wallet WHERE faction_id='atreides'"));assertEquals(new BigDecimal("5.00"),scalar(c,"SELECT balance FROM dune_staff_bank_wallet WHERE account_key='network'"));assertEquals(new BigDecimal("80.00"),scalar(c,"SELECT crafting_sink FROM dune_clan_kit_fee_allocations"));assertThrows(SQLException.class,()->bank.treasuryFee(c,ctx,id));c.rollback();assertEquals(new BigDecimal("15.00"),scalar(c,"SELECT balance FROM dune_faction_bank_wallet"));assertEquals(new BigDecimal("5.00"),scalar(c,"SELECT SUM(delta) FROM dune_staff_bank_ledger"));}}
 @Test void rollbackRestoresPaymentBothTaxesSinkReceiptAndOrder()throws Exception{try(Connection c=open()){c.setAutoCommit(false);UUID id=UUID.randomUUID();s.operation(c,id,ctx,"kit");s.payDunemarks(c,ctx);bank.treasuryFee(c,ctx,id);s.orderDunemarks(c,id,ctx);c.rollback();assertEquals(new BigDecimal("250.00"),s.wallet(c,UUID.fromString(ctx.uuid())));for(String table:List.of("dune_faction_bank_wallet","dune_faction_bank_ledger","dune_staff_bank_wallet","dune_staff_bank_ledger","dune_clan_kit_fee_allocations","dune_clan_kit_orders","dune_clan_operations"))assertEquals(0,scalar(c,"SELECT COUNT(*) FROM "+table).intValue());}}
 @Test void missingUnknownFactionFailsClosedInsteadOfInferringFromClan()throws Exception{try(Connection c=open()){for(String faction:List.of("", "Aerdrecht", "unknown")){try(PreparedStatement q=c.prepareStatement("UPDATE dune_players SET faction=? WHERE uuid=?")){q.setString(1,faction);q.setString(2,ctx.uuid());q.executeUpdate();}c.setAutoCommit(false);s.payDunemarks(c,ctx);assertThrows(SQLException.class,()->bank.treasuryFee(c,ctx,UUID.randomUUID()));c.rollback();assertEquals(new BigDecimal("250.00"),s.wallet(c,UUID.fromString(ctx.uuid())));c.setAutoCommit(true);}try(Statement q=c.createStatement()){q.execute("DELETE FROM dune_players");}c.setAutoCommit(false);assertThrows(SQLException.class,()->bank.treasuryFee(c,ctx,UUID.randomUUID()));c.rollback();}}
}
